          argsText: "{}",
          approval: { id: approval.id, prompt: approval.prompt },
        };
      }
      return {
        type: "tool-call",
        toolCallId: part.id,
        toolName: part.name,
        args: {},
        argsText: "{}",
        result: { ...(TOOL_RESULT[part.status] ?? {}), preview: part.preview ?? "" },
        isError: part.status === "error",
      };
    }

    default:
      return null;
  }
}

function attachmentParts(attachments: ChatAttachment[]) {
  return attachments.map((attachment) => ({
    id: attachment.id,
    type: attachment.contentType.startsWith("image/") ? ("image" as const) : ("document" as const),
    name: attachment.name,
    contentType: attachment.contentType,
    status: { type: "complete" as const },
    content: [
      {
        type: "file" as const,
        data: attachment.id,
        mimeType: attachment.contentType,
        filename: attachment.name,
      },
    ],
  }));
}

/**
 * A Studio turn as the runtime renders it.
 *
 * `content` stays the concatenated prose so history replays byte-identically;
 * `parts` is what the thread shows.
 */
export function toThreadMessageLike(message: ChatMessage): ThreadMessageLike {
  if (message.role === "notice") {
    return {
      id: message.id,
      role: "system",
      content: [{ type: "text", text: message.content }],
    };
  }

  const parts = (message.parts ?? []).flatMap((part) => {
    const converted = toPart(part);
    return converted ? [converted] : [];
  });

  const content: readonly LikePart[] =
    parts.length > 0
      ? parts
      : message.content
        ? [{ type: "text", text: message.content }]
        : [];

  const failed = message.error !== undefined;

  return {
    id: message.id,
    role: message.role,
    content,
    ...(message.role === "user" && message.attachments?.length
      ? { attachments: attachmentParts(message.attachments) }
      : {}),
    ...(failed
      ? {
          status: {
            type: "incomplete" as const,
            reason: "error" as const,
            error: message.error as never,
          },
        }
      : {}),
    ...(failed || message.retryText
      ? {
          metadata: {
            custom: {
              ...(message.error ? { error: message.error } : {}),
              ...(message.retryText ? { retryText: message.retryText } : {}),
            },
          },
        }
      : {}),
  };
}

function readCustom(message: ThreadMessage): Record<string, unknown> {
  return (message.metadata?.custom ?? {}) as Record<string, unknown>;
}

/**
 * The inverse: a runtime message back in the Studio's own model.
 *
 * The runtime hands a branch switch back as the originals it was given, so this
 * is only needed when a message arrives from somewhere else — an import, or a
 * future remote thread.
 */
export function toChatMessage(
  message: ThreadMessage,
  parentId: string | null = null,
): ChatMessage {
  const text = message.content
    .filter((part) => part.type === "text")
    .map((part) => (part as unknown as { text: string }).text)
    .join("");

  const custom = readCustom(message);
  const parts: ChatPart[] = [];

  for (const part of message.content) {
    switch (part.type) {
      case "text":
        parts.push({ kind: "text", text: part.text });
        break;

      case "reasoning":
        parts.push({ kind: "reasoning", text: part.text });
        break;

      case "source":
        parts.push({
          kind: "source",
          id: part.id,
          title: part.sourceType === "url" ? (part.title ?? part.url) : part.title,
          mediaType: part.sourceType === "document" ? part.mediaType : "text/html",
          ...(part.sourceType === "document" && part.filename
            ? { filename: part.filename }
            : {}),
        });
        break;

      case "tool-call": {
        const result = part.result as { status?: string; preview?: string } | undefined;
        const approval = part.approval;
        const awaiting = approval !== undefined && approval.approved === undefined && !part.result;
        parts.push({
          kind: "tool",
          id: part.toolCallId,
          name: part.toolName,
          status: awaiting
            ? "running"
            : part.isError
              ? "error"
              : result?.status === "declined"
                ? "declined"
                : "ok",
          ...(result?.preview ? { preview: result.preview } : {}),
          ...(awaiting ? { approval: { id: approval.id, prompt: approval.prompt ?? "" } } : {}),
        });
        break;
      }

      case "data":
        if (part.name === SURFACE_PART) {
          parts.push({
            kind: "ui",
            id: part.id ?? `ui-${parts.length}`,
            node: part.data as UiNode,
          });
        }
        break;

      default:
        break;
    }
  }

  const attachments: ChatAttachment[] | undefined = message.attachments?.length
    ? message.attachments.map((attachment) => ({
        id: attachment.id,
        name: attachment.name,
        contentType: attachment.contentType ?? "application/octet-stream",
        size: 0,
      }))
    : undefined;

  const role = message.role === "system" ? "notice" : message.role;

  return {
    id: message.id,
    parentId,
    role,
    content: text,
    ...(parts.length ? { parts } : {}),
    ...(attachments ? { attachments } : {}),
    ...(custom.error ? { error: custom.error as StudioError } : {}),
    ...(custom.retryText ? { retryText: String(custom.retryText) } : {}),
  };
}

/** The readable text of one appended message, for the Studio's send path. */
export function textOf(message: { content: string | readonly { type: string }[] }): string {
  if (typeof message.content === "string") {
    return message.content.trim();
  }
  return message.content
    .filter((part) => part.type === "text")
    .map((part) => (part as unknown as { text: string }).text)
    .join("\n")
    .trim();
}

metadata.preview:
/**
 * Turning a dropped file into something the model can actually read.
 *
 * The client owns this because only the client has the bytes: the sidecar
 * receives extracted text (or a data URL for an image), never a file handle.
 * Extraction is bounded so one large attachment cannot crowd out the
 * conversation, and it is silent about failure — a file we cannot read is shown
 * as a name, not dressed up as content.
 */

import type { AttachmentAdapter, CompleteAttachment, PendingAttachment } from "@assistant-ui/react";

import type { ChatAttachment } from "../types";

/** How much of a text file the model sees. */
export const MAX_ATTACHMENT_CHARS = 20_000;

/** A single image, bounded so a data URL cannot bloat the request. */
export const MAX_IMAGE_BYTES = 5 * 1024 * 1024;

display.text:
/**
 * Turning a dropped file into something the model can actually read.
 *
 * The client owns this because only the client has the bytes: the sidecar
 * receives extracted text (or a data URL for an image), never a file handle.
 * Extraction is bounded so one large attachment cannot crowd out the
 * conversation, and it is silent about failure — a file we cannot read is shown
 * as a name, not dressed up as content.
 */

import type { AttachmentAdapter, CompleteAttachment, PendingAttachment } from "@assistant-ui/react";

import type { ChatAttachment } from "../types";

/** How much of a text file the model sees. */
export const MAX_ATTACHMENT_CHARS = 20_000;

/** A single image, bounded so a data URL cannot bloat the request. */
export const MAX_IMAGE_BYTES = 5 * 1024 * 1024;

export const ATTACHMENT_ACCEPT = [
  "text/*",
  ".md",
  ".mdx",
  ".json",
  ".csv",
  ".yaml",
  ".yml",
  ".log",
  "image/png",
  "image/jpeg",
  "image/webp",
  "image/gif",
].join(",");

const TEXT_LIKE = /^(text\/|application\/(json|yaml|x-yaml)$)/;
const SUPPORTED_IMAGE_TYPES = new Set(
  ATTACHMENT_ACCEPT.split(",").filter((type) => type.startsWith("image/")),
);

export function isTextLike(name: string, contentType: string): boolean {
  if (TEXT_LIKE.test(contentType)) {
    return true;
  }
  return /\.(md|mdx|json|csv|ya?ml|txt|log)$/i.test(name);
}

export function isImageLike(contentType: string): boolean {
  return contentType.startsWith("image/");
}

/**
 * Why a dropped or pasted file cannot become an attachment, or null if it can.
 *
 * The file input already honours `accept`; a drop bypasses it, so the same
 * rule is applied here rather than letting an unreadable file become a chip
 * that promises content the model will never see.
 */
export function attachmentRejection(file: File): string | null {
  if (isImageLike(file.type)) {
    if (!SUPPORTED_IMAGE_TYPES.has(file.type)) {
      return `${file.name} is not an image the studio can read (PNG, JPEG, WebP, GIF).`;
    }
    if (file.size > MAX_IMAGE_BYTES) {
      return `${file.name} is larger than ${Math.floor(MAX_IMAGE_BYTES / (1024 * 1024))} MB.`;
    }
    return null;
  }
  if (isTextLike(file.name, file.type)) {
    return null;
  }
  return `${file.name} is not a text or image file the studio can read.`;
}

/** A short size for an attachment chip; empty when there is nothing to say. */
export function formatFileSize(bytes: number): string {
  if (!bytes || bytes < 0) {
    return "";
  }
  if (bytes < 1024) {
    return `${bytes} B`;
  }
  if (bytes < 1024 * 1024) {
    return `${Math.round(bytes / 1024)} KB`;
  }
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function readAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result ?? ""));
    reader.onerror = () => reject(reader.error ?? new Error("Could not read the file."));
    reader.readAsDataURL(file);
  });
}

/**
 * Prepare one file for a turn. Never throws: an unreadable file becomes a
 * name-only attachment so the user can still see what they attached.
 */
export async function prepareAttachment(file: File): Promise<ChatAttachment> {
  const base: ChatAttachment = {
    id: crypto.randomUUID(),
    name: file.name,
    contentType: file.type || "application/octet-stream",
    size: file.size,
  };

  try {
    if (isImageLike(base.contentType) && file.size <= MAX_IMAGE_BYTES) {
      return { ...base, dataUrl: await readAsDataUrl(file) };
    }
    if (isTextLike(file.name, base.contentType)) {
      const text = await file.text();
      return { ...base, text: text.slice(0, MAX_ATTACHMENT_CHARS) };
    }
  } catch {
    /* a file we cannot read is still an attachment the user chose */
  }

  return base;
}

/**
 * The adapter the runtime uses for `ComposerPrimitive.Attachments`.
 *
 * Prepared attachments are kept by id so `onNew` can hand the turn the same
 * extraction the composer showed.
 */
export function createAttachmentAdapter(): AttachmentAdapter {
  return {
    accept: ATTACHMENT_ACCEPT,

    async add({ file }): Promise<PendingAttachment> {
      return {
        id: crypto.randomUUID(),
        type: isImageLike(file.type) ? "image" : file.type ? "document" : "file",
        name: file.name,
        contentType: file.type || "application/octet-stream",
        file,
        status: { type: "requires-action", reason: "composer-send" },
      };
    },

    async remove(): Promise<void> {
      // Nothing to release: the file never left the browser.
    },

    async send(attachment): Promise<CompleteAttachment> {
      const file = attachment.file;
      const ready = file
        ? await prepareAttachment(file)
        : {
            id: attachment.id,
            name: attachment.name,
            contentType: attachment.contentType ?? "application/octet-stream",
            size: 0,
          };
      ATTACHMENTS.set(attachment.id, ready);
      return {
        ...attachment,
        status: { type: "complete" },
        content: [
          {
            type: "file",
            data: attachment.id,
            mimeType: ready.contentType,
            filename: ready.name,
          },
        ],
      };
    },
  };
}

/** Process-wide, because the runtime adapter outlives a render. */
const ATTACHMENTS = new Map<string, ChatAttachment>();

/** The extraction for one attachment, for showing what was actually sent. */
export function preparedAttachmentById(id: string): ChatAttachment | undefined {
  return ATTACHMENTS.get(id);
}

/** The extraction for the attachments the runtime handed back on a send. */
export function preparedAttachments(
  attachments: readonly { id: string }[] | undefined,
): ChatAttachment[] {
  if (!attachments?.length) {
    return [];
  }
  return attachments.flatMap((attachment) => {
    const ready = ATTACHMENTS.get(attachment.id);
    return ready ? [ready] : [];
  });
}

